/**
 * Birds for the Norman Shades view (norman-view.js): small 3D models of seven kinds, each with
 * its own shape, colours and way of flying.
 *
 * GENERATED by scripts/build_birds.mjs from the Light Control card's src/house/birds.ts
 * (github.com/kedube/ha-light-control, by the same author), with its types removed and nothing
 * else changed. Change the birds in that card and build this again; do not edit it here.
 *
 * Loaded by the view only when a photograph has birds in its sky, at the view's own ?v= stamp.
 */

// Birds in flight, as small 3D models: a body with a head, a bill and a tail, and two wings that
// bend at the wrist, each kind with its own shape, colors and way of flying. Every frame poses
// them, lights them as the house is lit, and lays them on the screen as triangles, which the sky
// pass fills in with smooth edges at any size.

export const KINDS = ['songbird', 'swallow', 'crow', 'gull', 'goose', 'hawk', 'bat'];

/** The most triangles a bird is drawn with. */
export const BIRD_TRIS = 80;
/**
 * Each bird is a row of the table the sky pass reads, in texels of four numbers. The first: where
 * it is on the screen (CSS pixels), how far it reaches and how many triangles it has. The second:
 * its depth, opacity and haze. Then three for each triangle: its corners, how far each is from the
 * viewer, and their colors, each packed into one number.
 */
export const BIRD_TEXELS = 2 + BIRD_TRIS * 3;
export const BIRD_FLOATS = BIRD_TEXELS * 4;

const TAU = Math.PI * 2;
const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, v));
const lerp = (a, b, t) => a + (b - a) * t;
const smooth = (a, b, v) => {
  const t = clamp((v - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
};
/** sRGB, 0–255, to the linear light the renderer works in. */
const linear = (c) => [(c[0] / 255) ** 2.2, (c[1] / 255) ** 2.2, (c[2] / 255) ** 2.2];
const turn = (u, v, a) => [
  u * Math.cos(a) - v * Math.sin(a),
  u * Math.sin(a) + v * Math.cos(a),
];

// ─── What each kind looks like ───────────────────────────────────────────────

const ring = (y, w, h, z, back, belly = back) => ({
  y,
  w,
  h,
  z,
  back,
  belly,
});

/** Two points across the wing, on its leading edge, thick with bone, and its thin trailing edge. */
function across(u, lead, trail, c, hand = false) {
  return [
    { u, v: lead, up: c.up, down: c.down, hand, fan: 0, thin: 0.7, tilt: 0.18 },
    { u, v: trail, up: c.upBehind ?? c.up, down: c.downBehind ?? c.down, hand, fan: 0, thin: 1, tilt: -0.12 },
  ];
}

const tip = (u, v, c) => ({
  u,
  v,
  up: c.up,
  down: c.down,
  hand: true,
  fan: 0,
  thin: 0.8,
  tilt: 0,
});

/**
 * One of the long primaries that stand apart at the tip of a broad wing, as a crow's or a hawk's:
 * its base across the hand (leading side first), the middle of its blunt end, and how far it fans.
 */
function finger(u, base, end, fan, root, ends) {
  const pivot = [u, (base[0] + base[1]) / 2];
  const du = end[0] - pivot[0];
  const dv = end[1] - pivot[1];
  const l = Math.hypot(du, dv) || 1;
  // Its end is a little over a quarter as wide as its base.
  const half = Math.abs(base[0] - base[1]) * 0.28;
  const side = [(-dv / l) * half, (du / l) * half];
  const feather = (fu, fv, c, thin) => ({
    u: fu,
    v: fv,
    up: c.up,
    down: c.down,
    hand: true,
    fan,
    pivot,
    thin,
    tilt: 0,
  });
  return [
    feather(u, base[0], root, 0.7),
    feather(end[0] + side[0], end[1] + side[1], ends, 1),
    feather(end[0] - side[0], end[1] - side[1], ends, 1),
    feather(u, base[1], root, 0.7),
  ];
}

/** Triangles along a wing given as pairs across it from the body out, ending at a point if the count is odd. */
function strip(count) {
  const tris = [];
  for (let i = 0; i + 3 < count; i += 2) tris.push([i, i + 2, i + 3], [i, i + 3, i + 1]);
  if (count % 2) tris.push([count - 3, count - 1, count - 2]);
  return tris;
}

const fingers = (from, count) =>
  Array.from({ length: count }, (_, i) => [
    [from + i * 4, from + i * 4 + 1, from + i * 4 + 2],
    [from + i * 4, from + i * 4 + 2, from + i * 4 + 3],
  ]).flat();

