// ─── How each kind flies ─────────────────────────────────────────────────────

const STROKES = {
  songbird: { rate: 11, up: 1.15, down: -0.95, downstroke: 0.5, flex: 0.75, lag: 0.35 },
  swallow: { rate: 7.5, up: 0.75, down: -0.6, downstroke: 0.52, flex: 0.5, lag: 0.3 },
  crow: { rate: 3.6, up: 0.6, down: -0.55, downstroke: 0.55, flex: 0.45, lag: 0.35 },
  gull: { rate: 2.7, up: 0.45, down: -0.42, downstroke: 0.55, flex: 0.32, lag: 0.38 },
  goose: { rate: 3.1, up: 0.5, down: -0.55, downstroke: 0.53, flex: 0.3, lag: 0.32 },
  hawk: { rate: 2.6, up: 0.42, down: -0.42, downstroke: 0.55, flex: 0.25, lag: 0.3 },
  bat: { rate: 9.5, up: 1, down: -0.9, downstroke: 0.5, flex: 0.45, lag: 0.5 },
};

const pose = (p) => ({ lift: 0, hand: 0, fold: 0, sweep: 0, spread: 0, tail: 0, bob: 0, ...p });

/** Between beats: a songbird shuts its wings, a gull glides on bent wings, a hawk soars on spread ones. */
const RESTS = {
  songbird: pose({ lift: 0.12, fold: 1 }),
  swallow: pose({ lift: 0.05, hand: -0.05, fold: 0.4, sweep: 0.2, tail: 0.2 }),
  crow: pose({ lift: 0.07, fold: 0.05, spread: 0.7, tail: 0.4 }),
  gull: pose({ lift: 0.17, hand: -0.38, fold: 0.14, sweep: 0.08, tail: 0.1 }),
  hawk: pose({ lift: 0.15, hand: 0.03, sweep: -0.04, spread: 1, tail: 1 }),
};

const mixPose = (a, b, k) => ({
  lift: lerp(a.lift, b.lift, k),
  hand: lerp(a.hand, b.hand, k),
  fold: lerp(a.fold, b.fold, k),
  sweep: lerp(a.sweep, b.sweep, k),
  spread: lerp(a.spread, b.spread, k),
  tail: lerp(a.tail, b.tail, k),
  bob: lerp(a.bob, b.bob, k),
});

/**
 * A wingbeat at a point in its cycle (whole numbers at the top of the stroke). The wings sweep down
 * spread wide, and come back up with the wrist bent, the hand trailing the arm both ways; the body
 * rises as they push down.
 */
function beat(at, s) {
  const p = at - Math.floor(at);
  const D = s.downstroke;
  const ease = (k) => (1 - Math.cos(Math.PI * k)) / 2;
  if (p < D) {
    const k = p / D;
    const lift = s.up + (s.down - s.up) * ease(k);
    const pace = Math.sin(Math.PI * k);
    return {
      lift,
      hand: s.lag * pace,
      fold: 0,
      sweep: -0.05 * pace,
      spread: 0.25,
      tail: 0.15,
      bob: (0.025 * ((s.up + s.down) / 2 - lift)) / (s.up - s.down),
    };
  }
  const k = (p - D) / (1 - D);
  const lift = s.down + (s.up - s.down) * ease(k);
  const pace = Math.sin(Math.PI * k);
  return {
    lift,
    hand: -s.lag * pace,
    fold: s.flex * pace,
    sweep: 0.12 * pace,
    spread: 0.25 - 0.8 * pace,
    tail: 0.15,
    bob: (0.025 * ((s.up + s.down) / 2 - lift)) / (s.up - s.down),
  };
}

/** Beats its wings for `flap` seconds of every `length`, and rests them for the rest, easing between the two. */
function flapThenRest(t, length, flap, ease, s, rest) {
  const c = ((t % length) + length) % length;
  if (c < flap) return mixPose(beat(c * s.rate, s), rest, smooth(flap - ease, flap, c));
  return mixPose(beat(0, s), rest, 1 - smooth(length - ease, length, c));
}

/** How a bird of a kind holds its wings `t` seconds into its flight; `phase` and `seed` are its own. */
export function posture(kind, t, phase, seed) {
  const base = STROKES[kind];
  const s = { ...base, rate: base.rate * (0.92 + 0.16 * seed[3]) };
  const offset = seed[0] * 10;
  switch (kind) {
    case 'songbird':
      // Bounding: a burst of quick beats, then the wings shut tight for a moment.
      return flapThenRest(t + offset, 0.7 + seed[1] * 0.25, 0.36, 0.05, s, RESTS.songbird);
    case 'swallow':
      return flapThenRest(t + offset, 1 + seed[1] * 0.5, 0.55, 0.12, s, RESTS.swallow);
    case 'gull':
      // A few slow beats, then a long glide on bent wings.
      return flapThenRest(t + offset, 4.5 + seed[1] * 2.5, 1.5, 0.35, s, RESTS.gull);
    case 'crow':
      // Rowing along, gliding now and then.
      return flapThenRest(t + offset, 8 + seed[1] * 5, 6.6 + seed[1] * 4, 0.25, s, RESTS.crow);
    case 'hawk': {
      // Soaring, with a few heavy beats now and then.
      const length = 6.5 + seed[1] * 4;
      const c = (((t + offset) % length) + length) % length;
      return mixPose(RESTS.hawk, beat(c * s.rate, s), smooth(0, 0.15, c) * (1 - smooth(0.8, 1, c)));
    }
    case 'bat': {
      // A flutter, never quite the same beat twice: its rate wanders 1.5 beats a second either way.
      const at = s.rate * t - (1.5 / 2.3) * Math.cos(t * 2.3 + seed[2] * 9) + phase / TAU;
      return beat(at, s);
    }
    default:
      return beat(t * s.rate + phase / TAU, s);
  }
}

// ─── Laying a bird on the screen ─────────────────────────────────────────────

/** Daylight, for when nobody says what the sky is like. */
export const DAYLIGHT = {
  dir: [0.22, 0.766, 0.604],
  color: [5.2, 4.7, 4],
  ambient: [
    [0.21, 0.3, 0.39],
    [0.2, 0.29, 0.37],
    [0.09, 0.19, 0.42],
    [0.27, 0.29, 0.2],
    [0.23, 0.32, 0.43],
    [0.2, 0.28, 0.37],
  ],
};

/** Around each ring of the body: the top, then round by the right. */
const AROUND = [90, 30, -30, -90, -150, 150].map((a) => (a * Math.PI) / 180);

const sub = (a, b) => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
const cross = (a, b) => [
  a[1] * b[2] - a[2] * b[1],
  a[2] * b[0] - a[0] * b[2],
  a[0] * b[1] - a[1] * b[0],
];
const dot = (a, b) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
const unit = (a) => {
  const l = Math.hypot(a[0], a[1], a[2]) || 1;
  return [a[0] / l, a[1] / l, a[2] / l];
};

const prepared = new Map ();

function prepare(kind) {
  const cached = prepared.get(kind);
  if (cached) return cached;
  const look = LOOKS[kind];
  const rump = look.body[0];
  // The body runs on into the tail, flattening over the feathers that cover the tail's base.
  const rings = [
    ring(
      rump.y - look.tail.length * 0.35,
      look.tail.base * 0.8,
      rump.h * 0.3,
      rump.z,
      look.tail.up[0],
      look.tail.down[0],
    ),
    ...look.body,
  ];
  const points = [];
  const normals = [];
  const albedo = [];
  const radius = (r) => (r.w + r.h) / 2;
  rings.forEach((r, i) => {
    const before = rings[Math.max(0, i - 1)];
    const after = rings[Math.min(rings.length - 1, i + 1)];
    // Where the body widens forward, its surface faces back a little, and forward where it narrows.
    const slope = after === before ? 0 : -(radius(after) - radius(before)) / (after.y - before.y);
    for (const a of AROUND) {
      points.push([r.w * Math.cos(a), r.y, r.z + r.h * Math.sin(a)]);
      normals.push(unit([(Math.cos(a) / r.w) * radius(r), slope * 0.6, (Math.sin(a) / r.h) * radius(r)]));
      const top = smooth(-0.35, 0.35, Math.sin(a));
      albedo.push(linear(r.back.map((v, k) => lerp(r.belly[k], v, top))));
    }
  });
  const n = rings.length * 6;
  const head = rings[rings.length - 1];
  points.push([0, look.bill.y, look.bill.z], [0, rings[0].y - 0.02, rings[0].z]);
  normals.push(unit([0, 1, (look.bill.z - head.z) * 2]), [0, -1, 0]);
  albedo.push(linear(look.bill.color), albedo[0]);
  const tris = [];
  for (let i = 0; i + 1 < rings.length; i++) {
    for (let j = 0; j < 6; j++) {
      const a = i * 6 + j;
      const b = i * 6 + ((j + 1) % 6);
      tris.push([a, b, b + 6], [a, b + 6, a + 6]);
    }
  }
  for (let j = 0; j < 6; j++) {
    tris.push([(rings.length - 1) * 6 + j, (rings.length - 1) * 6 + ((j + 1) % 6), n]);
    tris.push([j, (j + 1) % 6, n + 1]);
  }
  // Every face turned outward.
  for (const t of tris) {
    const face = cross(sub(points[t[1]], points[t[0]]), sub(points[t[2]], points[t[0]]));
    const out = [0, 1, 2].map((k) => normals[t[0]][k] + normals[t[1]][k] + normals[t[2]][k]);
    if (dot(face, out) < 0) [t[1], t[2]] = [t[2], t[1]];
  }
  const result = {
    look,
    points,
    normals,
    albedo,
    tris,
    up: look.wing.map((f) => linear(f.up)),
    down: look.wing.map((f) => linear(f.down)),
    tail: {
      up: [linear(look.tail.up[0]), linear(look.tail.up[1])],
      down: [linear(look.tail.down[0]), linear(look.tail.down[1])],
    },
  };
  prepared.set(kind, result);
  return result;
}

/** The renderer's film curve (`develop` in the shaders), so that a bird is exposed as the house and the sky are. */
function develop(c) {
  const peak = Math.max(c[0], c[1], c[2]);
  const toWhite = smooth(1.5, 12, peak) * 0.6;
  let packed = 0;
  for (let i = 0; i < 3; i++) {
    const x = (c[i] + (peak - c[i]) * toWhite) * 0.82;
    const f = clamp((x * (2.51 * x + 0.03)) / (x * (2.43 * x + 0.59) + 0.14), 0, 1);
    packed = packed * 256 + Math.round(f ** (1 / 2.2) * 255);
  }
  return packed;
}

function lighting(light, toEye) {
  // World space has y up; plan space has z up.
  const sun = [light.dir[0], light.dir[2], light.dir[1]];
  const a = light.ambient;
  // A bird flies high above the ground, so its underside sees more of the sky than the house's walls do.
  const around = [0, 1, 2].map((i) => (a[0][i] + a[1][i] + a[4][i] + a[5][i]) / 4);
  const below = a[3].map((v, i) => lerp(v, around[i], 0.5));
  return {
    sun,
    color: light.color,
    sky: [a[0], a[1], a[2], below, a[4], a[5]],
    half: toEye ? unit([sun[0] + toEye[0], sun[1] + toEye[1], sun[2] + toEye[2]]) : null,
  };
}

/**
 * The color of a surface, packed, lit as the house is: by the sun or the moon, and by the sky and
 * the ground. Thin feathers and skin let the sun through when it is behind them, colored by what it
 * passes through; glossy ones gleam where they catch it.
 */
function shade(albedo, n, lit, look, thin = 0) {
  const facing = dot(n, lit.sun);
  const sun = Math.max(0, facing);
  const through = facing < 0 ? -facing * look.glow * thin : 0;
  const gleam = lit.half && facing > 0 ? look.sheen * Math.max(0, dot(n, lit.half)) ** 30 : 0;
  const [x, y, z] = n;
  const ax = lit.sky[x < 0 ? 1 : 0];
  const az = lit.sky[z < 0 ? 3 : 2];
  const ay = lit.sky[y < 0 ? 5 : 4];
  const out = [0, 0, 0];
  for (let i = 0; i < 3; i++) {
    const sky = x * x * ax[i] + z * z * az[i] + y * y * ay[i];
    const k = lit.color[i];
    out[i] = albedo[i] * (k * sun + sky + look.tint[i] * k * through) + k * gleam;
  }
  return develop(out);
}

/** How far the wings sweep back at the shoulder, and the hands at the wrist, when they are folded. */
const FOLD_ARM = 1.3;
const FOLD_HAND = 1.9;
/** How much shorter the arm grows as the elbow bends, and narrower the wing as its feathers slide together. */
const ELBOW = 0.55;
const NARROW = 0.45;

/** The wing on one side (1 the right, −1 the left) as it is held: its points, and which way its upper side faces. */
function poseWing(look, p, side, H, L) {
  const root = look.wing[0].u;
  const wrist = look.wing[look.wrist];
  const back = p.sweep + FOLD_ARM * p.fold;
  const bend = FOLD_HAND * p.fold + 0.5 * p.sweep;
  const shorter = 1 - ELBOW * p.fold;
  const narrower = 1 - NARROW * p.fold;
  const arm = (u, v) => {
    const [du, dv] = turn((u - root) * shorter, v * narrower, -back);
    return [root + du, dv];
  };
  const [wu, wv] = arm(wrist.u, wrist.v);
  const raise = p.lift;
  const tilt = p.lift + p.hand;
  const shoulder = look.shoulder * L;
  const wx = root + (wu - root) * Math.cos(raise);
  const wz = (wu - root) * Math.sin(raise);
  const armUp = [-side * Math.sin(raise), 0, Math.cos(raise)];
  const handUp = [-side * Math.sin(tilt), 0, Math.cos(tilt)];
  return look.wing.map((f) => {
    if (!f.hand) {
      const [u, v] = arm(f.u, f.v);
      return {
        at: [side * (root + (u - root) * Math.cos(raise)) * H, v * H, shoulder + (u - root) * Math.sin(raise) * H],
        normal: armUp,
      };
    }
    let u = f.u;
    let v = f.v;
    if (f.pivot) {
      const [du, dv] = turn(u - f.pivot[0], v - f.pivot[1], f.fan * p.spread);
      u = f.pivot[0] + du;
      v = f.pivot[1] + dv;
    }
    const [du, dv] = turn(u - wrist.u, (v - wrist.v) * narrower, -(back + bend));
    return {
      at: [side * (wx + du * Math.cos(tilt)) * H, (wv + dv) * H, shoulder + (wz + du * Math.sin(tilt)) * H],
      normal: handUp,
    };
  });
}

/** The tail as it is held, in shares of the length: its points, whether each is at the end, and its triangles. */
function poseTail(look, spread) {
  const t = look.tail;
  const rump = look.body[0];
  const y0 = rump.y;
  const z = rump.z;
  const e = lerp(t.closed, t.open, clamp(spread, 0, 1));
  const y1 = y0 - t.length;
  switch (t.shape) {
    case 'fork':
      // Long outer feathers, with a deep notch between them.
      return {
        at: [
          [-t.base, y0, z],
          [-e, y1, z],
          [0, y0 - t.length * 0.46, z],
          [e, y1, z],
          [t.base, y0, z],
        ],
        end: [0, 1, 1, 1, 0],
        tris: [
          [0, 1, 2],
          [0, 2, 4],
          [4, 2, 3],
        ],
      };
    case 'fan': {
      // Fanned out round the rump, every feather the same length.
      const wide = Math.atan2(e, t.length);
      const at = [
        [0, y0, z],
        [-t.base, y0, z],
      ];
      for (let i = 0; i < 5; i++) {
        const a = lerp(-wide, wide, i / 4);
        at.push([Math.sin(a) * t.length, y0 - Math.cos(a) * t.length, z]);
      }
      at.push([t.base, y0, z]);
      return {
        at,
        end: [0, 0, 1, 1, 1, 1, 1, 0],
        tris: [
          [0, 1, 2],
          [0, 2, 3],
          [0, 3, 4],
          [0, 4, 5],
          [0, 5, 6],
          [0, 6, 7],
        ],
      };
    }
    default: {
      const at = [
        [-t.base, y0, z],
        [t.base, y0, z],
        [e, y1, z],
        [-e, y1, z],
      ];
      const tris = [
        [0, 1, 2],
        [0, 2, 3],
      ];
      if (t.shape === 'round') {
        at.push([0, y1 - t.length * 0.08, z]);
        tris.push([3, 2, 4]);
      }
      return { at, end: [0, 0, 1, 1, 1], tris };
    }
  }
}

/** Whether a triangle on the screen turns the way that shows the side its corners' order faces (see the tests). */
const facing = (a, b, c) => (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);

/**
 * Lays a bird on the screen: poses it, lights it and writes it into `row` for the sky pass. Returns
 * false when it cannot be seen: behind the viewer, or off the edges of the picture.
 */
export function layBird(
  row,
  kind,
  span,
  frame,
  p,
  lens,
  light,
  opacity,
  haze,
) {
  const prep = prepare(kind);
  const { look } = prep;
  const L = look.length * span;
  const H = span / 2;
  const { at, forward: F, right: R, up: U } = frame;
  const place = (q) => [
    at[0] + R[0] * q[0] + F[0] * q[1] + U[0] * q[2],
    at[1] + R[1] * q[0] + F[1] * q[1] + U[1] * q[2],
    at[2] + R[2] * q[0] + F[2] * q[1] + U[2] * q[2],
  ];
  const aim = (n) => [
    R[0] * n[0] + F[0] * n[1] + U[0] * n[2],
    R[1] * n[0] + F[1] * n[1] + U[1] * n[2],
    R[2] * n[0] + F[2] * n[1] + U[2] * n[2],
  ];
  const onScreen = (q) => {
    const s = lens.point(place(q));
    return s ? { x: s.x, y: s.y, z: s.distance } : null;
  };
  const middle = lens.point(at);
  if (!middle) return false;
  const lit = lighting(light, lens.eye ? unit(sub(lens.eye, at)) : null);

  let count = 0;
  let reach = 0;
  let x0 = Infinity;
  let y0 = Infinity;
  let x1 = -Infinity;
  let y1 = -Infinity;
  const put = (a, b, c, ca, cb, cc) => {
    if (count >= BIRD_TRIS) return;
    const o = (2 + count * 3) * 4;
    row[o] = a.x;
    row[o + 1] = a.y;
    row[o + 2] = b.x;
    row[o + 3] = b.y;
    row[o + 4] = c.x;
    row[o + 5] = c.y;
    row[o + 6] = a.z;
    row[o + 7] = b.z;
    row[o + 8] = c.z;
    row[o + 9] = ca;
    row[o + 10] = cb;
    row[o + 11] = cc;
    for (const q of [a, b, c]) {
      reach = Math.max(reach, Math.hypot(q.x - middle.x, q.y - middle.y));
      x0 = Math.min(x0, q.x);
      y0 = Math.min(y0, q.y);
      x1 = Math.max(x1, q.x);
      y1 = Math.max(y1, q.y);
    }
    count++;
  };

  // The body: only the side facing the viewer, which hides the rest.
  const body = [];
  for (const q of prep.points) {
    const s = onScreen([q[0] * L, q[1] * L, q[2] * L]);
    if (!s) return false;
    body.push(s);
  }
  const bodyColor = [];
  // Feathers scatter a little of the sun round into the shade beneath the body.
  const colorAt = (i) => (bodyColor[i] ??= shade(prep.albedo[i], aim(prep.normals[i]), lit, look, 0.12));
  for (const [i, j, k] of prep.tris) {
    if (facing(body[i], body[j], body[k]) <= 0) continue;
    put(body[i], body[j], body[k], colorAt(i), colorAt(j), colorAt(k));
  }

  /**
   * A thin surface, seen from above or below: the wings and the tail. Each point has the way its
   * upper side faces, how the curve of the wing tips it, how thin it is, and its two colors.
   */
  const plate = (
    tris,
    local,
    screen,
    ups,
    tilt,
    thin,
    up,
    down,
  ) => {
    const colors = new Map ();
    for (const tri of tris) {
      let [i, j, k] = tri;
      // Its corners in the order that faces its upper side.
      const face = cross(sub(local[j], local[i]), sub(local[k], local[i]));
      const upper = [0, 1, 2].map((n) => ups[i][n] + ups[j][n] + ups[k][n]);
      if (dot(face, upper) < 0) [j, k] = [k, j];
      const top = facing(screen[i], screen[j], screen[k]) > 0;
      const color = (v) => {
        const key = top ? v : -1 - v;
        let c = colors.get(key);
        if (c === undefined) {
          // Curved over the top, hollow beneath: the leading edge faces forward, the trailing edge back.
          const t = tilt(v);
          const n = top
            ? aim(unit([ups[v][0], ups[v][1] + t, ups[v][2]]))
            : aim(unit([-ups[v][0], -ups[v][1] + t * 0.5, -ups[v][2]]));
          c = shade(top ? up(v) : down(v), n, lit, look, thin(v));
          colors.set(key, c);
        }
        return c;
      };
      put(screen[i], screen[j], screen[k], color(i), color(j), color(k));
    }
  };

  for (const side of [1, -1]) {
    const wing = poseWing(look, p, side, H, L);
    const screen = [];
    for (const f of wing) {
      const s = onScreen(f.at);
      if (!s) return false;
      screen.push(s);
    }
    plate(
      look.wingTris,
      wing.map((f) => f.at),
      screen,
      wing.map((f) => f.normal),
      (i) => look.wing[i].tilt,
      (i) => look.wing[i].thin,
      (i) => prep.up[i],
      (i) => prep.down[i],
    );
  }

  const tail = poseTail(look, p.tail);
  const tailAt = tail.at.map((q) => [q[0] * L, q[1] * L, q[2] * L]);
  const tailScreen = [];
  for (const q of tailAt) {
    const s = onScreen(q);
    if (!s) return false;
    tailScreen.push(s);
  }
  plate(
    tail.tris,
    tailAt,
    tailScreen,
    tailAt.map(() => [0, 0, 1]),
    () => 0,
    (i) => (tail.end[i] ? 0.8 : 0.4),
    (i) => prep.tail.up[tail.end[i]],
    (i) => prep.tail.down[tail.end[i]],
  );

  const margin = 4;
  if (!count || x1 < -margin || y1 < -margin || x0 > lens.width + margin || y0 > lens.height + margin) return false;
  row[0] = middle.x;
  row[1] = middle.y;
  row[2] = reach + 1;
  row[3] = count;
  row[4] = middle.depth;
  row[5] = opacity;
  row[6] = haze;
  row[7] = 0;
  return true;
}
